package ru.eclipsru.mikapital;
import android.content.Context;
import android.os.Handler;
import android.os.Looper;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.zip.GZIPInputStream;

public final class Updater {
  public static final String REPO="https://github.com/eclipsru/Mi-Kapital";
  private final Context context; private final NativeStore store; private final Handler main=new Handler(Looper.getMainLooper());
  private final Object stateLock=new Object(); private final AtomicBoolean installing=new AtomicBoolean();
  private volatile JSONObject state; private volatile JSONObject pending; private volatile boolean busy; private volatile String verifiedVersion;
  public Updater(Context context,NativeStore store){this.context=context;this.store=store;state=info();restorePending();}
  public JSONObject info(){try{JSONObject value=new JSONObject();value.put("platform","android");value.put("phase","idle");value.put("version",activeVersion());value.put("shellVersion",String.valueOf(BuildConfig.SHELL_VERSION));value.put("mode","files");value.put("percent",0);value.put("transferred",0);value.put("total",0);value.put("packaged",true);return value;}catch(Exception e){throw new RuntimeException(e);}}
  private void patch(JSONObject values)throws Exception{String json;synchronized(stateLock){Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();state.put(key,values.get(key));}json=state.toString();}dispatch(json);}
  private void dispatch(String json){main.post(()->{if(context instanceof MainActivity)((MainActivity)context).evaluate("window.dispatchEvent(new CustomEvent('mi-kapital-update',{detail:"+json+"}))");});}
  private void emit(){dispatch(stateJson());}
  public String stateJson(){synchronized(stateLock){return state.toString();}}
  private void reset(JSONObject value){synchronized(stateLock){state=value;}emit();}
  private String phase(){synchronized(stateLock){return state.optString("phase");}}
  private static int compare(String a,String b){String[] x=a.split("\\."),y=b.split("\\.");for(int i=0;i<3;i++){int result=Integer.compare(Integer.parseInt(x[i]),Integer.parseInt(y[i]));if(result!=0)return result;}return 0;}
  public String activeVersion(){try{JSONObject pointer=new JSONObject(NativeStore.read(store.file("updates/active.json")));String version=pointer.getString("version");if(pointer.optBoolean("quarantined")||pointer.getInt("shellVersion")!=BuildConfig.SHELL_VERSION||compare(version,BuildConfig.VERSION_NAME)<=0)return BuildConfig.VERSION_NAME;File root=new File(store.file("updates/bundles"),version);JSONObject manifest=new JSONObject(NativeStore.read(new File(root,"manifest.json")));if(validate(manifest,version)&&bundleMatchesCached(root,manifest,version))return version;}catch(Exception ignored){}return BuildConfig.VERSION_NAME;}
  public File activeRoot(){String version=activeVersion();return version.equals(BuildConfig.VERSION_NAME)?null:new File(store.file("updates/bundles"),version+"/dist");}
  private boolean bundleMatchesCached(File root,JSONObject manifest,String version)throws Exception{if(version.equals(verifiedVersion))return true;if(!bundleMatches(root,manifest))return false;verifiedVersion=version;return true;}
  private boolean bundleMatches(File root,JSONObject manifest)throws Exception{File dist=new File(root,"dist");JSONArray files=manifest.getJSONArray("files");for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);File file=new File(dist,f.getString("path"));if(!file.isFile()||file.length()!=f.getLong("size")||!NativeStore.hash(Files.readAllBytes(file.toPath())).equals(f.getString("sha256")))return false;}return true;}
  private boolean validate(JSONObject manifest,String version)throws Exception{if(!"mi-kapital-update-2".equals(manifest.optString("format"))||!manifest.getString("version").equals(version)||!manifest.getString("tag").equals("v"+version))return false;JSONArray files=manifest.getJSONArray("files");if(files.length()==0||files.length()>500)return false;Set<String> paths=new HashSet<>();long total=0;for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String path=f.getString("path");if(path.length()>240||path.startsWith("/")||path.contains("..")||path.contains("\\")||path.matches(".*[\\x00-\\x1f].*")||!paths.add(path)||!f.getString("sha256").matches("[a-f0-9]{64}")||!f.getString("asset").equals("update-"+f.getString("sha256")+".gz"))return false;for(String part:path.split("/"))if(part.isEmpty()||part.equals("."))return false;long size=f.getLong("size");if(size<0||size>20000000)return false;total+=size;}return paths.contains("index.html")&&total<=80000000;}
  private byte[] download(String address)throws Exception{return download(address,0);}
  private byte[] download(String address,int redirects)throws Exception{if(redirects>6)throw new IOException("Too many redirects");URL url=new URL(address);if(!url.getProtocol().equals("https")||!(url.getHost().equals("github.com")||url.getHost().endsWith(".githubusercontent.com")))throw new IOException("Untrusted update host");HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(30000);connection.setRequestProperty("User-Agent","Mi-Kapital-Android/2");connection.setRequestProperty("Cache-Control","no-cache");int code=connection.getResponseCode();if(code>=300&&code<400){String location=connection.getHeaderField("Location");connection.disconnect();return download(new URL(url,location).toString(),redirects+1);}if(code!=200){connection.disconnect();throw new IOException("GitHub HTTP "+code);}try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[]buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>20000000)throw new IOException("Update too large");out.write(buf,0,n);}return out.toByteArray();}finally{connection.disconnect();}}
  private Map<String,File> known()throws Exception{Map<String,File> result=new HashMap<>();File cache=store.file("updates/cache");File[] cached=cache.listFiles();if(cached!=null)for(File f:cached)if(f.getName().matches("[a-f0-9]{64}")&&NativeStore.hash(Files.readAllBytes(f.toPath())).equals(f.getName()))result.put(f.getName(),f);File root=activeRoot();if(root!=null)collect(root,"",result);else{JSONObject builtin=new JSONObject(NativeStore.read(context.getAssets().open("builtin.json")));JSONArray files=builtin.getJSONArray("files");for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String sha=f.getString("sha256");if(result.containsKey(sha))continue;File temp=store.file("updates/cache/"+sha);UpdateFiles.ensureParent(temp);try(InputStream in=context.getAssets().open("web/"+f.getString("path"));OutputStream out=new FileOutputStream(temp)){byte[]buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}if(!NativeStore.hash(Files.readAllBytes(temp.toPath())).equals(sha))throw new IOException("Built-in asset checksum");result.put(sha,temp);}}return result;}
  private void collect(File root,String relative,Map<String,File> result)throws Exception{File[] children=root.listFiles();if(children==null)return;for(File f:children){String path=relative.isEmpty()?f.getName():relative+"/"+f.getName();if(f.isDirectory())collect(f,path,result);else result.put(NativeStore.hash(Files.readAllBytes(f.toPath())),f);}}
  private void restorePending(){try{File file=store.file("updates/pending.json");if(!file.isFile())return;JSONObject manifest=new JSONObject(NativeStore.read(file));String version=manifest.getString("version");if(!version.matches("\\d+\\.\\d+\\.\\d+")||manifest.optInt("androidShellVersion",1)>BuildConfig.SHELL_VERSION||compare(version,activeVersion())<=0){file.delete();return;}File target=new File(store.file("updates/bundles"),version);if(validate(manifest,version)&&bundleMatches(target,manifest)){pending=manifest;patch(new JSONObject().put("phase","ready").put("mode","files").put("targetVersion",version).put("percent",100).put("message","Обновление загружено и готово к установке"));}}catch(Exception ignored){}}
  public synchronized void check(){if(busy||"ready".equals(phase()))return;busy=true;new Thread(()->{try{patch(new JSONObject().put("phase","checking").put("message",JSONObject.NULL).put("targetVersion",JSONObject.NULL).put("percent",0).put("transferred",0).put("total",0));JSONObject manifest=new JSONObject(new String(download(REPO+"/releases/latest/download/update-manifest.json"),"UTF-8"));String version=manifest.getString("version");if(!version.matches("\\d+\\.\\d+\\.\\d+")||!validate(manifest,version))throw new IOException("Неверный манифест");if(manifest.optInt("androidShellVersion",1)>BuildConfig.SHELL_VERSION){patch(new JSONObject().put("phase","ready").put("mode","native").put("targetVersion",version).put("message","Для этой версии нужен новый APK. Данные сохранятся."));return;}if(compare(version,activeVersion())<=0){patch(new JSONObject().put("phase","idle").put("checkedAt",new Date().toInstant().toString()).put("message","У вас актуальная версия"));return;}Map<String,File> known=known();JSONArray files=manifest.getJSONArray("files");List<JSONObject> missing=new ArrayList<>();long total=0;for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);if(!known.containsKey(f.getString("sha256"))){missing.add(f);total+=f.getLong("size");}}patch(new JSONObject().put("phase","downloading").put("targetVersion",version).put("files",missing.size()).put("total",total));long transferred=0;for(JSONObject f:missing){byte[] compressed=download(REPO+"/releases/download/"+manifest.getString("tag")+"/"+f.getString("asset"));ByteArrayOutputStream plain=new ByteArrayOutputStream();try(GZIPInputStream gzip=new GZIPInputStream(new ByteArrayInputStream(compressed))){byte[]buf=new byte[8192];int n;while((n=gzip.read(buf))!=-1){if(plain.size()+n>20000000)throw new IOException("Unpacked file too large");plain.write(buf,0,n);}}byte[]content=plain.toByteArray();if(content.length!=f.getInt("size")||!NativeStore.hash(content).equals(f.getString("sha256")))throw new IOException("Контрольная сумма не совпадает");File cache=store.file("updates/cache/"+f.getString("sha256"));store.atomicBytes(cache,content);known.put(f.getString("sha256"),cache);transferred+=content.length;patch(new JSONObject().put("transferred",transferred).put("percent",(int)(transferred*100/Math.max(1,total))));}File target=new File(store.file("updates/bundles"),version);File staging=store.file("updates/staging-"+System.currentTimeMillis());try{for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);File dest=new File(staging,"dist/"+f.getString("path"));dest.getParentFile().mkdirs();Files.copy(known.get(f.getString("sha256")).toPath(),dest.toPath(),StandardCopyOption.REPLACE_EXISTING);}if(!bundleMatches(staging,manifest))throw new IOException("Повторная проверка файлов не пройдена");store.atomic(new File(staging,"manifest.json"),manifest.toString());NativeStore.deleteTree(target);target.getParentFile().mkdirs();Files.move(staging.toPath(),target.toPath());}finally{NativeStore.deleteTree(staging);}store.atomic(store.file("updates/pending.json"),manifest.toString());pending=manifest;patch(new JSONObject().put("phase","ready").put("mode","files").put("percent",100).put("message",missing.isEmpty()?"Обновление уже загружено":"Загружены только изменившиеся файлы"));}catch(Exception e){try{patch(new JSONObject().put("phase","error").put("message","Не удалось обновиться: "+e.getMessage()+". Рабочая версия сохранена."));}catch(Exception ignored){}}finally{busy=false;}}).start();}
  public synchronized void quarantine(){try{String version=activeVersion();store.atomic(store.file("updates/active.json"),new JSONObject().put("version",version).put("shellVersion",BuildConfig.SHELL_VERSION).put("quarantined",true).toString());store.file("updates/pending.json").delete();pending=null;verifiedVersion=null;reset(info());}catch(Exception ignored){}}
  public synchronized String install(){if(!installing.compareAndSet(false,true))return "{\"ok\":false,\"message\":\"Обновление уже устанавливается\"}";try{String phase;String mode;JSONObject manifest;synchronized(stateLock){phase=state.optString("phase");mode=state.optString("mode");manifest=pending;}if(!"ready".equals(phase))return "{\"ok\":false,\"message\":\"Сначала загрузите обновление\"}";if("native".equals(mode)){((MainActivity)context).openExternal(REPO+"/releases/latest/download/Mi-Kapital-mobile.apk");return "{\"ok\":true}";}if(manifest==null)throw new IOException("Манифест не загружен");String version=manifest.getString("version");if(manifest.optInt("androidShellVersion",1)>BuildConfig.SHELL_VERSION)throw new IOException("Требуется новый APK");File target=new File(store.file("updates/bundles"),version);if(!validate(manifest,version)||!bundleMatches(target,manifest))throw new IOException("Файлы обновления повреждены; загрузите обновление заново");store.atomic(store.file("updates/active.json"),new JSONObject().put("version",version).put("shellVersion",BuildConfig.SHELL_VERSION).put("quarantined",false).toString());store.file("updates/pending.json").delete();pending=null;verifiedVersion=version;reset(info());main.post(()->((MainActivity)context).reload());return "{\"ok\":true}";}catch(Exception e){return "{\"ok\":false,\"message\":"+JSONObject.quote(e.getMessage())+"}";}finally{installing.set(false);}}
}
